class Solution:
    def calculateScore(self, s: str) -> int:
        score = 0
        pos = [[] for _ in range(26)]

        for i, char in enumerate(s):
            c_idx = ord(char) - 97
            mirror_idx = 25 - c_idx

            if pos[mirror_idx]:
                j = pos[mirror_idx].pop()
                score += i - j
            else:
                pos[c_idx].append(i)

        return score

import math
from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])

        # Space optimization: keep track of the DP state for the previous row
        # dp[j][k] will store the maximum coins at column j with k neutralizations
        dp = [[-math.inf] * 3 for _ in range(n)]

        # Base case for the starting cell
        if coins[0][0] >= 0:
            dp[0][0] = coins[0][0]
        else:
            dp[0][0] = coins[0][0]
            dp[0][1] = 0

        for i in range(m):
            next_dp = [[-math.inf] * 3 for _ in range(n)]
            for j in range(n):
                if i == 0 and j == 0:
                    # Inherit base case if we're at the start
                    next_dp[0][0] = dp[0][0]
                    next_dp[0][1] = dp[0][1]
                    next_dp[0][2] = dp[0][2]
                    continue

                for k in range(3):
                    # 1. Option: Do not use a neutralization on the current cell
                    best_prev = -math.inf
                    if i > 0:
                        best_prev = max(best_prev, dp[j][k])
                    if j > 0:
                        best_prev = max(best_prev, next_dp[j-1][k])

                    if best_prev != -math.inf:
                        next_dp[j][k] = max(next_dp[j][k], best_prev + coins[i][j])

                    # 2. Option: Use a neutralization on the current cell (if possible and needed)
                    if k > 0 and coins[i][j] < 0:
                        best_prev_k1 = -math.inf
                        if i > 0:
                            best_prev_k1 = max(best_prev_k1, dp[j][k-1])
                        if j > 0:
                            best_prev_k1 = max(best_prev_k1, next_dp[j-1][k-1])

                        if best_prev_k1 != -math.inf:
                            next_dp[j][k] = max(next_dp[j][k], best_prev_k1)

            dp = next_dp

        return int(max(dp[n-1]))

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        # dp[x][d] stores max length of subsequence ending with value x and last absolute diff exactly d
        dp = [[1] * 300 for _ in range(301)]

        # max_dp[x][d] stores max length of subsequence ending with value x and last absolute diff >= d
        max_dp = [[1] * 300 for _ in range(301)]

        seen = []
        seen_set = set()

        for x in nums:
            temp_dp = dp[x]

            for y in seen:
                d = abs(x - y)
                val = max_dp[y][d] + 1
                if val > temp_dp[d]:
                    temp_dp[d] = val

            # Update max_dp[x] using suffix maximums for O(1) lookups bounded closely
            mx = 1
            max_dp_x = max_dp[x]
            for d in range(299, -1, -1):
                if temp_dp[d] > mx:
                    mx = temp_dp[d]
                max_dp_x[d] = mx

            if x not in seen_set:
                seen_set.add(x)
                seen.append(x)

        # The answer will be the longest sequence across all explored values.
        # Checking d=0 spans constraints representing the max diffs safely >= 0.
        ans = 1
        for v in seen:
            if max_dp[v][0] > ans:
                ans = max_dp[v][0]

        return ans

from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Sort events primarily by timestamp.
        # If timestamps are the same, process OFFLINE (0) before MESSAGE (1).
        # This accurately models the requirement that status changes occur before messages.
        events.sort(key=lambda x: (int(x[1]), 0 if x[0] == "OFFLINE" else 1))

        mentions = [0] * numberOfUsers
        # return_online_time tracks when a user will be back online. 
        # Initialized to 0, since initial timestamps are >= 1, all users start online.
        return_online_time = [0] * numberOfUsers

        for event in events:
            if event[0] == "OFFLINE":
                user = int(event[2])
                # The user will come back online exactly 60 time units after going offline
                return_online_time[user] = int(event[1]) + 60
            else:  # "MESSAGE"
                t = int(event[1])
                tokens = event[2].split()
                for token in tokens:
                    if token == "ALL":
                        for i in range(numberOfUsers):
                            mentions[i] += 1
                    elif token == "HERE":
                        for i in range(numberOfUsers):
                            # A user is online if they either haven't gone offline or their offline period has ended
                            if return_online_time[i] <= t:
                                mentions[i] += 1
                    else:
                        # Extract user id from string formatted as "id<number>"
                        user_id = int(token[2:])
                        mentions[user_id] += 1

        return mentions

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        if not groups:
            return []

        max_group = max(groups)

        # best_assigned[x] will store the smallest index j such that elements[j] divides x
        best_assigned = [-1] * (max_group + 1)

        for j, E in enumerate(elements):
            # If the element is larger than the maximum group size, it cannot divide any group size
            if E > max_group:
                continue

            # If best_assigned[E] is already set, it means either E or a divisor of E 
            # appeared at an earlier index. In either case, that earlier element will 
            # also divide any multiple of E and will win the tie-breaker for smallest index.
            # Thus, we can safely skip processing E.
            if best_assigned[E] != -1:
                continue

            # Mark all multiples of E with the current index j, if not already marked
            for k in range(E, max_group + 1, E):
                if best_assigned[k] == -1:
                    best_assigned[k] = j

        return [best_assigned[g] for g in groups]

from typing import List

class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        candidates = []
        for row, limit in zip(grid, limits):
            if limit > 0:
                # Get the largest 'limit' elements from the current row
                candidates.extend(sorted(row, reverse=True)[:limit])

        # Sort all the eligible candidates in descending order
        candidates.sort(reverse=True)

        # The answer is the sum of the top 'k' candidates
        return sum(candidates[:k])

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True

        first = {}
        last = {}
        for i, char in enumerate(s):
            if char not in first:
                first[char] = i
            last[char] = i

        intervals = []
        n = len(s)

        # Find the minimal valid special substring starting at each character's first occurrence
        for char in first:
            L = first[char]
            R = last[char]
            valid = True
            i = L
            while i <= R:
                c = s[i]
                # If a character inside the current window has its first occurrence before L, 
                # then a valid substring cannot start at L.
                if first[c] < L:
                    valid = False
                    break
                # Expand the right boundary to encompass the last occurrence of the current character
                if last[c] > R:
                    R = last[c]
                i += 1

            if valid:
                # The valid substring cannot be the entire string itself
                if L == 0 and R == n - 1:
                    continue
                intervals.append((L, R))

        # Greedily find the maximum number of disjoint valid substrings
        # By sorting intervals based on their end position
        intervals.sort(key=lambda x: x[1])

        count = 0
        end = -1
        for L, R in intervals:
            if L > end:
                count += 1
                end = R

        return count >= k

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Precompute factorials for quick lookup
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        # Determine the total number of valid alternating permutations
        if n % 2 == 1:
            total_ways = fact[(n + 1) // 2] * fact[n // 2]
        else:
            total_ways = 2 * fact[n // 2] * fact[n // 2]

        # If k is larger than the total possible valid permutations, return empty list
        if k > total_ways:
            return []

        available = list(range(1, n + 1))
        ans = []

        rem_odds = (n + 1) // 2
        rem_evens = n // 2

        # Build the permutation position by position
        for i in range(n):
            for x in available:
                # Check if the chosen number 'x' satisfies the parity constraints
                if i == 0:
                    if n % 2 == 1 and x % 2 == 0:
                        continue  # If n is odd, the sequence must strictly start with an odd number
                else:
                    if x % 2 == ans[-1] % 2:
                        continue  # Parity must alternate with the previous element

                # Calculate the number of ways to complete the permutation if 'x' is placed here
                if x % 2 == 1:
                    ways = fact[rem_odds - 1] * fact[rem_evens]
                else:
                    ways = fact[rem_odds] * fact[rem_evens - 1]

                # If k falls within the 'ways', 'x' is our choice for the current position
                if k <= ways:
                    ans.append(x)
                    available.remove(x)
                    if x % 2 == 1:
                        rem_odds -= 1
                    else:
                        rem_evens -= 1
                    break
                else:
                    # Otherwise, skip these 'ways' permutations and check the next valid number
                    k -= ways

        return ans

from itertools import combinations_with_replacement

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        l_str = str(l - 1)
        r_str = str(r)

        # Helper function to count numbers <= limit_str that contain at least one '0'
        def count_has_zero_le(limit_str):
            if limit_str == "0":
                return 0
            limit_val = int(limit_str)
            limit_len = len(limit_str)
            no_zero = 0
            # Add up all numbers with fewer digits than limit that have no '0'
            for L in range(1, limit_len):
                no_zero += 9 ** L

            # Add up all numbers with the same length as limit that have no '0' and are <= limit
            for i in range(limit_len):
                limit_digit = int(limit_str[i])
                if limit_digit == 0:
                    break
                no_zero += (limit_digit - 1) * (9 ** (limit_len - 1 - i))
            else:
                no_zero += 1 # exact match if it has no zeros

            return limit_val - no_zero

        # Since any number containing '0' has a digit product of 0, 
        # and 0 is divisible by any sum (sum is > 0 for positive numbers),
        # all numbers containing at least one '0' are beautiful numbers.
        has_zero_r = count_has_zero_le(r_str)
        has_zero_l = count_has_zero_le(l_str)
        ans = has_zero_r - has_zero_l

        no_zero_r = 0
        no_zero_l = 0

        r_len = len(r_str)
        l_len = len(l_str) if l_str != "0" else 0
        max_len = r_len

        # Precompute factorials for fast permutation math
        fact = [1] * 10
        for i in range(1, 10):
            fact[i] = fact[i-1] * i

        # Helper to count how many permutations of `counts` are lexicographically <= limit_str
        def count_le(counts, L, limit_str, total_perms):
            ways_le = 0
            curr_counts = list(counts)
            rem_len = L

            for i in range(L):
                limit_digit = int(limit_str[i])
                if limit_digit == 0:
                    break

                for d in range(1, limit_digit):
                    if curr_counts[d] > 0:
                        ways_le += total_perms * curr_counts[d] // rem_len

                if curr_counts[limit_digit] > 0:
                    total_perms = total_perms * curr_counts[limit_digit] // rem_len
                    curr_counts[limit_digit] -= 1
                    rem_len -= 1
                else:
                    break
            else:
                ways_le += 1
            return ways_le

        # Generate all multisets (combinations) of digits 1-9
        for L in range(1, max_len + 1):
            for combo in combinations_with_replacement(range(1, 10), L):
                S = sum(combo)
                P = 1
                for x in combo:
                    P *= x

                # If product is divisible by sum, count permutations of this multiset
                if P % S == 0:
                    counts = [0] * 10
                    for d in combo:
                        counts[d] += 1

                    ways = fact[L]
                    for c in counts:
                        if c > 1:
                            ways //= fact[c]

                    if L < r_len:
                        no_zero_r += ways
                    elif L == r_len:
                        no_zero_r += count_le(counts, L, r_str, ways)

                    if l_str != "0":
                        if L < l_len:
                            no_zero_l += ways
                        elif L == l_len:
                            no_zero_l += count_le(counts, L, l_str, ways)

        ans += (no_zero_r - no_zero_l)
        return ans

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        ones_count = 0
        prev_zero_len = 0
        curr_zero_len = 0
        max_gain = 0

        # Traverse the binary string to find '1's count and evaluate '0' blocks
        for char in s:
            if char == '1':
                ones_count += 1
                if curr_zero_len > 0:
                    # If we already have a previous '0' block, we calculate the gain
                    # from merging the prev_zero_len and curr_zero_len.
                    if prev_zero_len > 0:
                        max_gain = max(max_gain, prev_zero_len + curr_zero_len)

                    # The current '0' block becomes the previous '0' block for the next potential gap
                    prev_zero_len = curr_zero_len
                    curr_zero_len = 0
            else:
                curr_zero_len += 1

        # After the loop completes, check if the string ended on a '0' block
        # that could be paired with the last registered 'prev_zero_len'.
        if curr_zero_len > 0:
            if prev_zero_len > 0:
                max_gain = max(max_gain, prev_zero_len + curr_zero_len)

        return ones_count + max_gain

from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))

        def find(i):
            if parent[i] == i:
                return i
            parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
                return True
            return False

        sets = [set(p) for p in properties]
        components = n

        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    if union(i, j):
                        components -= 1

        return components

import sys

def count_snake(x):
    if x < 10:
        return 0
    S = str(x)
    D = len(S)
    ans = 0

    # Lengths strictly less than D
    for d in range(2, D):
        for k in range(1, 10):
            ans += k**(d - 1)

    # Length exactly D, top digit strictly less than S[0]
    s0 = int(S[0])
    for k in range(1, s0):
        ans += k**(D - 1)

    # Length exactly D, top digit equal to S[0]
    for i in range(1, D):
        si = int(S[i])
        limit = min(si, s0)
        ans += limit * (s0**(D - 1 - i))
        if si >= s0:
            break
    else:
        # If we never broke, it means all digits after the first are strictly less than s0
        # This means the number x itself is a Snake number.
        ans += 1

    return ans

