import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return
    n = int(data[0])

    MOD = 998244353

    # Calculate counts and sums for elements of each possible decimal length
    c_count = {}
    S_sum = {}
    for L in range(1, 7):
        start = 10**(L-1)
        end = min(n, 10**L - 1)
        if start <= end:
            c_count[L] = (end - start + 1)
            S_sum[L] = (start + end) * c_count[L] // 2 % MOD

    L_list = list(c_count.keys())

    def poly_mul(poly1, poly2):
        res = [0] * (len(poly1) + len(poly2) - 1)
        for i, c1 in enumerate(poly1):
            for j, c2 in enumerate(poly2):
                res[i+j] = (res[i+j] + c1 * c2) % MOD
        return res

    def poly_add(poly1, poly2):
        res = [0] * max(len(poly1), len(poly2))
        for i in range(len(poly1)):
            res[i] = (res[i] + poly1[i]) % MOD
        for i in range(len(poly2)):
            res[i] = (res[i] + poly2[i]) % MOD
        return res

    v = {L: (10**L - 1) % MOD for L in L_list}

    # Construct the small degree polynomials A(t), B(t), C(t)
    A = [1]
    for L in L_list:
        A = poly_mul(A, [1, v[L]])

    B = [0]
    for L in L_list:
        temp = [c_count[L] * v[L] % MOD]
        for M in L_list:
            if M != L:
                temp = poly_mul(temp, [1, v[M]])
        B = poly_add(B, temp)

    C = [0]
    for L in L_list:
        temp = [S_sum[L]]
        for M in L_list:
            if M != L:
                temp = poly_mul(temp, [1, v[M]])
        C = poly_add(C, temp)

    # Precompute modular inverses up to n
    inv = [0] * (n + 1)
    if n >= 1:
        inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # Iteratively compute coefficients of P(t)
    p = [0] * (n + 1)
    p[0] = 1

    len_B = len(B)
    len_A = len(A)
    len_C = len(C)

    for k in range(1, n + 1):
        sum_b = 0
        limit_B = min(k, len_B)
        for i in range(limit_B):
            sum_b += p[k - 1 - i] * B[i]

        sum_a = 0
        limit_A = min(k + 1, len_A)
        for i in range(1, limit_A):
            sum_a += (k - i) * p[k - i] * A[i]

        p[k] = (sum_b - sum_a) % MOD * inv[k] % MOD

    # Iteratively compute coefficients of Q(t)
    q = [0] * n
    for k in range(n):
        sum_c = 0
        limit_C = min(k + 1, len_C)
        for i in range(limit_C):
            sum_c += p[k - i] * C[i]

        sum_qa = 0
        limit_A = min(k + 1, len_A)
        for i in range(1, limit_A):
            sum_qa += q[k - i] * A[i]

        q[k] = (sum_c - sum_qa) % MOD

    # Compute final integral outcome sum
    ans = 0
    for k in range(n):
        ans = (ans + q[k] * inv[k + 1]) % MOD

    # Factor in N! permutations multiplier factor
    fact = 1
    for i in range(1, n + 1):
        fact = (fact * i) % MOD

    ans = (ans * fact) % MOD
    print(ans)

if __name__ == '__main__':
    solve()

import sys

def solve():
    # Read all tokens from standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    A = input_data[1]

    # Initialize the base level (leaves of the tree)
    vals = [int(x) for x in A]
    costs = [1] * (3**N)

    length = 3**N

    # Process level by level bottom-up
    for _ in range(N):
        new_length = length // 3

        for i in range(new_length):
            idx = i * 3
            v1, v2, v3 = vals[idx], vals[idx+1], vals[idx+2]
            c1, c2, c3 = costs[idx], costs[idx+1], costs[idx+2]

            s = v1 + v2 + v3

            if s == 3 or s == 0:
                # All 3 children are the same. We need to flip the 2 cheapest children.
                vals[i] = 1 if s == 3 else 0
                if c1 > c2:
                    costs[i] = c2 + c3 if c1 > c3 else c1 + c2
                else:
                    costs[i] = c1 + c3 if c2 > c3 else c1 + c2
            else:
                if s == 2:
                    # Two 1s and one 0. We need to flip one of the 1s (the cheapest one).
                    vals[i] = 1
                    if v1 == 0:
                        costs[i] = c2 if c2 < c3 else c3
                    elif v2 == 0:
                        costs[i] = c1 if c1 < c3 else c3
                    else:
                        costs[i] = c1 if c1 < c2 else c2
                else:
                    # Two 0s and one 1. We need to flip one of the 0s (the cheapest one).
                    vals[i] = 0
                    if v1 == 1:
                        costs[i] = c2 if c2 < c3 else c3
                    elif v2 == 1:
                        costs[i] = c1 if c1 < c3 else c3
                    else:
                        costs[i] = c1 if c1 < c2 else c2

        length = new_length

    # The root node's cost yields the absolute minimum bits required to flip the string outcome
    print(costs[0])

if __name__ == '__main__':
    solve()

import sys

def main():
    # Read all standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    s = input_data[0]
    st = []

    # Process each character using a stack
    for c in s:
        if c == '(': 
            st.append(c)
        elif c == '[': 
            st.append(c)
        elif c == '<': 
            st.append(c)
        elif c == ')':
            if not st or st[-1] != '(':
                print("No")
                return
            st.pop()
        elif c == ']':
            if not st or st[-1] != '[':
                print("No")
                return
            st.pop()
        elif c == '>':
            if not st or st[-1] != '<':
                print("No")
                return
            st.pop()

    # If the stack is empty at the end, all brackets were matched properly
    if not st:
        print("Yes")
    else:
        print("No")

if __name__ == '__main__':
    main()

import sys

def solve():
    # Read all tokens from standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])

    last_seen = {}
    min_len = float('inf')

    # Process the sequence A
    for i in range(1, n + 1):
        val = int(input_data[i])
        if val in last_seen:
            current_len = i - last_seen[val] + 1
            if current_len < min_len:
                min_len = current_len
        # Update the most recent index where this value was seen
        last_seen[val] = i

    # Output the result
    if min_len == float('inf'):
        print(-1)
    else:
        print(min_len)

if __name__ == '__main__':
    solve()

